def solve(inputs: dict) -> float:
    A = inputs['A']
    B = inputs['B']

    # Sum the floor divisions for each position
    total = sum(a // b for a, b in zip(A, B))

    return float(total)

scripts.lcg_generator:
def solve(inputs: dict) -> float:
    X = inputs['SEED']
    A = inputs['A']
    B = inputs['B']
    M = inputs['M']
    K = inputs['K']

    # Apply the LCG recurrence K times
    for _ in range(K):
        X = (A * X + B) % M

    return float(X)

scripts.factorial_mod:
def solve(inputs: dict) -> float:
    n = inputs['N']
    mod = inputs['MOD']

    # Compute factorial modulo mod
    result = 1
    for i in range(1, n + 1):
        result = (result * i) % mod

    return float(result)

